{
  "@context": "https://schema.org/", 
  "@type": "Product", 
  "name": "2-Day Trip to Morocco from Gibraltar",
  "image": "https://www.tangierexcursions.com/wp-content/uploads/2025/07/2-day-trip-to-Morocco-from-Gibraltar.jpg",
  "description": "Looking for a quick escape to a whole new world? This 2-day trip to Morocco from Gibraltar is the perfect blend of adventure, culture, and scenic beauty. In just two days, you’ll cross continents, ride camels by the beach, explore the blue alleys of Chefchaouen, and discover the ancient charm of Tangier—all with the ease of private transport and guided experiences.",
  "brand": {
    "@type": "Brand",
    "name": "Tangier Excursions"
  },
  "sku": "TGT-13338",
  "mpn": "TGT-13338",
  "offers": {
    "@type": "AggregateOffer",
    "url": "https://www.tangierexcursions.com/best-tangier-tours/2-day-trip-to-morocco-from-gibraltar/",
    "priceCurrency": "EUR",
    "lowPrice": "357",
    "highPrice": "605",
    "offerCount": "1000"
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "5",
    "bestRating": "5",
    "worstRating": "4.9",
    "ratingCount": "92"
  },
  "review": {
    "@type": "Review",
    "name": "Enchanting 2-Day Morocco Escape from Gibraltar",
    "reviewBody": "We had an amazing 2-day adventure to Morocco from Gibraltar with Tangier Excursions! Everything was smooth—from crossing the border and ferry ride to the private car and local guides. Tangier was lively and full of charm, and Chefchaouen completely stole our hearts with its blue streets and relaxed vibe. The riad was beautiful, and the camel ride along the beach was such a fun touch. Highly recommend this tour if you want a real taste of Morocco in just two days!",
    "author": {"@type": "Person", "name": "Emily R."},
    "publisher": {"@type": "Organization", "name": "Tangier Excursions"}
  }
}

