{
  "@context": "https://schema.org/", 
  "@type": "Product", 
  "name": "2-Day Trip to Morocco from Malaga",
  "image": "https://www.tangierexcursions.com/wp-content/uploads/2025/07/2-day-trip-to-Morocco-from-Malaga.jpg",
  "description": "If you’re looking for an unforgettable experience that blends exotic culture, stunning landscapes, and authentic traditions, this 2-day trip to Morocco from Malaga is the perfect escape. In just two days, you’ll travel from Spain to North Africa, crossing the Strait of Gibraltar and discovering the magical blue town of Chefchaouen and the vibrant city of Tangier.",
