    "lowPrice": "517",
    "highPrice": "855",
    "offerCount": "1000"
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "5",
    "bestRating": "5",
    "worstRating": "4.9",
    "ratingCount": "75"
  },
  "review": {
    "@type": "Review",
    "name": "Magical 2-Day Morocco Getaway from Malaga",
    "reviewBody": "An unforgettable experience arranged by Tangier Excursions! Everything was smooth—from the ferry to the camel ride and exploring Chefchaouen. The Riad stay was lovely, and our guides made Morocco come alive. Perfect short escape from Malaga!",
    "author": {"@type": "Person", "name": "Sarah M."},
    "publisher": {"@type": "Organization", "name": "Tangier Excursions"}
  }
}

