{
  "@context": "https://schema.org/", 
  "@type": "Product", 
  "name": "2-Day Trip to Morocco from Seville",
  "image": "https://www.tangierexcursions.com/wp-content/uploads/2025/07/2-day-trip-to-Morocco-from-Seville.jpg",
  "description": "Join us on a once-in-a-lifetime 2-day trip to Morocco from Seville, where Europe meets Africa most magically. This short escape is perfect for travelers who want to experience the vibrant energy of Morocco while based in southern Spain. From charming blue alleys in Chefchaouen to the historic kasbahs of Tangier, this is a journey that blends culture, nature, and adventure.",
  "brand": {
    "@type": "Brand",
    "name": "Tangier Excursions"
  },
  "sku": "TGT-10178",
  "mpn": "TGT-10158",
