    "@type": "AggregateOffer",
    "url": "https://www.tangierexcursions.com/best-tangier-tours/2-day-trip-to-morocco-from-seville/",
    "priceCurrency": "EUR",
    "lowPrice": "517",
    "highPrice": "855",
    "offerCount": "1000"
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "5",
    "bestRating": "5",
    "worstRating": "4.9",
    "ratingCount": "135"
  },
  "review": {
    "@type": "Review",
    "name": "Unforgettable 2-Day Morocco Adventure from Seville",
    "reviewBody": "Our private 2-day Morocco tour with Tangier Excursions was absolutely amazing! Everything was smooth—from the pick-up in Seville to exploring Chefchaouen and walking through Tangier’s old medina. The camel ride and the Riad stay were highlights. It was the perfect mix of culture, adventure, and comfort!",
    "author": {"@type": "Person", "name": "James S."},
    "publisher": {"@type": "Organization", "name": "Tangier Excursions"}
  }
}

