{
  "@context": "https://schema.org/", 
  "@type": "Product", 
  "name": "3 Day Morocco Tour from Gibraltar",
  "image": "https://www.tangierexcursions.com/wp-content/uploads/2025/08/3-Day-Morocco-Tour-from-Gibraltar.jpg",
  "description": "Join us on a once-in-a-lifetime 3 day Morocco tour from Gibraltar, where Europe meets Africa most effortlessly. Just a short drive to Tarifa and a ferry ride across the Strait of Gibraltar, you will find yourself wandering through ancient kasbahs, riding camels by the Atlantic, exploring Morocco’s famous Blue City, and hiking through the breathtaking Akchour Valley.",
  "brand": {
    "@type": "Brand",
    "name": "Tangier Excursions"
  },
  "sku": "TGT-45478",
  "mpn": "TGT-41858",
