    "@type": "AggregateOffer",
    "url": "https://www.tangierexcursions.com/best-tangier-tours/3-day-morocco-tour-from-gibraltar/",
    "priceCurrency": "EUR",
    "lowPrice": "315",
    "highPrice": "741",
    "offerCount": "1000"
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "5",
    "bestRating": "5",
    "worstRating": "4.9",
    "ratingCount": "125"
  },
  "review": {
    "@type": "Review",
    "name": "Magical 3-Day Morocco Adventure from Gibraltar",
    "reviewBody": "Our 3-day trip to Morocco from Gibraltar with Tangier Excursions was unforgettable! From the ferry ride to Tangier, the camel ride on the beach, and exploring Chefchaouen’s blue streets to hiking the Akchour Valley, every moment was seamless and well-organized. The riads were cozy, the guides knowledgeable, and the scenery breathtaking. Highly recommended for a quick but immersive Moroccan experience!",
    "datePublished": "2025-6-10",
    "author": {"@type": "Person", "name": "Brian M."},
    "publisher": {"@type": "Organization", "name": "Tangier Excursions"}
  }
}

