{
  "@context": "https://schema.org/", 
  "@type": "Product", 
  "name": "4-Day Morocco Tour from Spain",
  "image": "https://www.tangierexcursions.com/wp-content/uploads/2026/01/4-day-morocco-tour-from-spain.jpg",
  "description": "This private 4-day Morocco tour from Spain to Tangier, Fes & Chefchaouen offers an ideal opportunity to learn about the exotic culture of Morocco in a short period of time. You may already be exploring Spain and planning to come to terms with a new culture while avoiding long hours of flights, then this trip is the one to vouch for.",
  "brand": {
    "@type": "Brand",
    "name": "Tangier Excursions LLC"
  },
  "sku": "MTS-25265",
  "mpn": "MTS-25237",
  "offers": {
    "@type": "AggregateOffer",
    "url": "https://www.tangierexcursions.com/best-tangier-tours/trip-tangier-to-fes-chefchaouen-4-days-3-nights/",
    "priceCurrency": "EUR",
    "lowPrice": "512",
    "highPrice": "921",
    "offerCount": "1000"
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "5",
    "bestRating": "5",
    "worstRating": "4.9",
    "ratingCount": "325"
  },
  "review": {
    "@type": "Review",
    "name": "Sarah Mitchell",
    "reviewBody": "Our 4-day Morocco tour from Spain with Tangier Excursions was absolutely fantastic. Everything was perfectly organized, from the ferry crossing to the beautiful riads and guided tours. Our private guide was knowledgeable, friendly, and made us feel comfortable at every step. Tangier, Fes, and Chefchaouen were all incredible, each with its own charm. The camel ride by the beach and walking through the old medinas were unforgettable highlights. If you’re looking for a smooth, authentic, and well-paced trip to Morocco, I highly recommend Tangier Excursions.",
    "author": {"@type": "Person", "name": "Tangier Excursions LLC"},
    "publisher": {"@type": "Organization", "name": "Tangier Excursions"}
  }
}

