{
  "@context": "https://schema.org/", 
  "@type": "Product", 
  "name": "Tangier and Tetouan Day Trip",
  "image": "https://www.tangierexcursions.com/wp-content/uploads/2019/03/Tetouan-Morocco.jpg",
  "description": "The popular Tangier and Tetouan day trip from Gibraltar, Sevilla, Malaga, Tarifa...etc is carefully designed to allow you to meet the real Moroccan hospitality on its own terms opening wide gates of discovery and opening up.

Tangier & Tetouan are the largest cities in the north of Morocco but are still shrouded in mystery as most visitors mistakenly dismiss the available opportunity to experience an intact culture.",
  "brand": {
    "@type": "Brand",
    "name": "Tangier Excursions"
  },
  "sku": "TNT-55758",
  "mpn": "TNT-65284",
  "offers": {
    "@type": "AggregateOffer",
    "url": "https://www.tangierexcursions.com/day-trips/day-trip-to-tangier-and-tetouan-from-gibraltar/",
    "priceCurrency": "EUR",
    "lowPrice": "55",
    "highPrice": "185",
    "offerCount": "785"
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "5",
    "bestRating": "5",
    "worstRating": "4.9",
    "ratingCount": "365"
  },
  "review": {
    "@type": "Review",
    "name": "Great Experience",
    "reviewBody": "It was a very, very enjoyable trip with Moha all along. Travelling alone for three girls in North Africa could sound intimidating, but Moha definitely eased everything out for us. From the steady drives, interesting local tours, authentic lunches, to his delightful sense of humor - we enjoyed ourselves so much around the Sahara Desert. Because Moha is such a friendly and easy-going tour guide, we had our itinerary completely to ourselves and we were able to speak out any needs/problems to him with no reserve. He even made a trip to his house to show us the daily lives of Moroccans - a side of the tour that you rarely get the chance to see! We are absolutely grateful for his hospitality. I would recommend everyone to book Tangier Excursions & Moha because of my wonderful time in Morocco.",
    "author": {"@type": "Person", "name": "Littie Sin"},
    "publisher": {"@type": "Organization", "name": "Tangier Excursions"}
  }
}

